// Google Sans Flex (SIL Open Font License 1.1), latin and latin-ext subsets
// of fonts.gstatic.com v26, weights 500 to 600 in one variable file each.
// Generated file: embedded in a PDF's HTML so that printing never waits on
// Google Fonts (Sacha 28/10/2026, « le PDF du Brief est super long »).

const LATIN =
  "";

const LATIN_EXT =
  "";

/** The @font-face rules of Google Sans Flex, the files inlined. */
export const GOOGLE_SANS_FLEX_FACES = [
  [
    LATIN_EXT,
    "U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF",
  ],
  [
    LATIN,
    "U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD",
  ],
]
  .map(
    ([file, range]) =>
      `@font-face { font-family: "Google Sans Flex"; font-style: normal; font-weight: 500 600; font-display: block; src: url(data:font/woff2;base64,${file}) format("woff2"); unicode-range: ${range}; }`,
  )
  .join("\n");
